export function generateLangChainCode(config) {
    if (config.strategy === 'markdown') {
        return `# LangChain Markdown Header Text Splitter
# Generated by RAG Chunk Visualizer (AstraMeld - https://astrameld.com)

from langchain_text_splitters import MarkdownHeaderTextSplitter, RecursiveCharacterTextSplitter

headers_to_split_on = [
    ("#", "Header 1"),
    ("##", "Header 2"),
    ("###", "Header 3"),
]

markdown_splitter = MarkdownHeaderTextSplitter(headers_to_split_on=headers_to_split_on)
md_header_splits = markdown_splitter.split_text(your_document_text)

# Subdivide large sections
text_splitter = RecursiveCharacterTextSplitter(
    chunk_size=${config.chunkSize},
    chunk_overlap=${config.chunkOverlap},
    separators=["\\n\\n", "\\n", " ", ""]
)

chunks = text_splitter.split_documents(md_header_splits)
print(f"Generated {len(chunks)} chunks.")
`;
    }
    if (config.strategy === 'sentence') {
        return `# LangChain Sentence-level / NLTK Text Splitter
# Generated by RAG Chunk Visualizer (AstraMeld - https://astrameld.com)

from langchain_text_splitters import NLTKTextSplitter

text_splitter = NLTKTextSplitter(
    chunk_size=${config.chunkSize},
    chunk_overlap=${config.chunkOverlap}
)

chunks = text_splitter.split_text(your_document_text)
print(f"Generated {len(chunks)} sentence-aware chunks.")
`;
    }
    return `# LangChain RecursiveCharacterTextSplitter
# Generated by RAG Chunk Visualizer (AstraMeld - https://astrameld.com)

from langchain_text_splitters import RecursiveCharacterTextSplitter

text_splitter = RecursiveCharacterTextSplitter(
    chunk_size=${config.chunkSize},
    chunk_overlap=${config.chunkOverlap},
    separators=["\\n\\n", "\\n", ". ", " ", ""]
)

chunks = text_splitter.split_text(your_document_text)
print(f"Generated {len(chunks)} chunks.")
`;
}
export function generateLlamaIndexCode(config) {
    if (config.strategy === 'sentence') {
        return `# LlamaIndex SentenceSplitter
# Generated by RAG Chunk Visualizer (AstraMeld - https://astrameld.com)

from llama_index.core.node_parser import SentenceSplitter
from llama_index.core import Document

splitter = SentenceSplitter(
    chunk_size=${config.chunkSize},
    chunk_overlap=${config.chunkOverlap}
)

document = Document(text=your_document_text)
nodes = splitter.get_nodes_from_documents([document])
print(f"Generated {len(nodes)} nodes.")
`;
    }
    if (config.strategy === 'markdown') {
        return `# LlamaIndex MarkdownNodeParser
# Generated by RAG Chunk Visualizer (AstraMeld - https://astrameld.com)

from llama_index.core.node_parser import MarkdownNodeParser
from llama_index.core import Document

parser = MarkdownNodeParser()
document = Document(text=your_document_text)
nodes = parser.get_nodes_from_documents([document])
print(f"Generated {len(nodes)} markdown section nodes.")
`;
    }
    return `# LlamaIndex TokenTextSplitter
# Generated by RAG Chunk Visualizer (AstraMeld - https://astrameld.com)

from llama_index.core.node_parser import TokenTextSplitter
from llama_index.core import Document

splitter = TokenTextSplitter(
    chunk_size=${config.chunkSize},
    chunk_overlap=${config.chunkOverlap},
    separator=" "
)

document = Document(text=your_document_text)
nodes = splitter.get_nodes_from_documents([document])
print(f"Generated {len(nodes)} nodes.")
`;
}
export function generateExportJson(config, metrics, chunks) {
    return JSON.stringify({
        generator: 'RAG Chunk Visualizer & Overlap Inspector',
        author: 'Ali Afzal Yousuf (AstraMeld)',
        url: 'https://astrameld.com',
        repository: 'https://github.com/3liAf/rag-chunk-visualizer',
        timestamp: new Date().toISOString(),
        config,
        metrics,
        chunks: chunks.map(c => ({
            index: c.index,
            charStart: c.charStart,
            charEnd: c.charEnd,
            length: c.text.length,
            estimatedTokens: c.tokenCount,
            overlapWithPrevious: c.overlapWithPrevious,
            overlapCharLength: c.overlapCharLength,
            isFracturedSentence: c.isFracturedSentence,
            text: c.text
        }))
    }, null, 2);
}
